.workspace-tools > button:hover, .workspace-tools > div > button:hover { background: var(--color-paper-deep); }
@media (max-width: 767.98px) {
  .mc-button { min-height: 44px; height: auto; padding-top: 10px; padding-bottom: 10px; white-space: normal; }
  .mc-input { min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) { .mc-button:enabled:hover { transform: none; } }

/* An open pinned bottom companion occupies the mobile navigation area too. */
@media (max-width: 767.98px) {
  .workspace-grid[data-companion-pinned="true"] .workspace-main:has(.workspace-full-height) { padding-bottom: 0; }
}
.workspace-main > .workspace-full-height:first-child { padding: 0; }

/* Keep return-to-top clear of the persistent rewrite command in the sidebar. */
@media (min-width: 768px) {
  .workspace-scroll-top { left: auto; right: 20px; }
  .workspace-background:has(.workspace-grid[data-companion-pinned="true"]) .workspace-scroll-top { right: calc(var(--spacing-companion) + 20px); }
}
