/* Workspace viewport geometry.
   CSS viewport units are resolved before root `zoom` is painted. Use the
   compensated height for every surface that must fill the physical viewport. */
.workspace-root {
  --app-viewport-height: calc(100dvh / var(--app-zoom, 1));
  --workspace-sticky-top: calc(var(--spacing-workspace-header) + env(safe-area-inset-top) + 8px);
}

.workspace-root,
.workspace-background {
  min-height: var(--app-viewport-height);
  min-width: 0;
}

.workspace-header {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: var(--spacing-workspace-header);
  padding: env(safe-area-inset-top) 24px 0;
  background: var(--color-paper-raised);
  border-bottom: 1px solid var(--color-line);
}

.workspace-brand { display: flex; align-items: center; gap: 12px; flex-shrink: 0; color: var(--color-ink); }
.workspace-monogram { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-sm); background: var(--color-accent); color: var(--color-paper-raised); font-family: var(--font-display); font-weight: 600; }
.workspace-dev { border: 1px solid var(--color-line); border-radius: var(--radius-sm); padding: 2px 6px; font: 10px var(--font-mono); color: var(--color-accent-deep); }
.workspace-tools { margin-left: auto; display: flex; align-items: center; gap: 8px; min-width: 0; }
.workspace-tools > button, .workspace-tools > div > button { min-height: 44px; min-width: 44px; }
.workspace-companion-toggle { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 8px 12px; border: 1px solid var(--color-line); border-radius: var(--radius-sm); color: var(--color-ink-soft); font-size: 13px; cursor: pointer; }
.workspace-companion-toggle:hover, .workspace-companion-toggle.is-active { color: var(--color-accent); background: var(--color-accent-tint); }
.workspace-display-popover {
  max-width: calc((100dvw - 24px) / var(--app-zoom, 1));
  max-height: calc((100dvh - 100px) / var(--app-zoom, 1));
}

.workspace-grid {
  display: grid;
  grid-template-columns: var(--workspace-sidebar-width) minmax(0, 1fr);
  align-items: start;
  min-width: 0;
}
.workspace-grid[data-sidebar="expanded"] { --workspace-sidebar-width: var(--spacing-workspace-sidebar); }
.workspace-grid[data-sidebar="collapsed"] { --workspace-sidebar-width: 64px; }
.workspace-grid[data-companion-pinned="true"] { padding-right: var(--spacing-companion); }

@media (min-width: 768px) {
  .workspace-companion { max-width: calc(45vw / var(--app-zoom, 1)); }
}

.workspace-sidebar {
  position: sticky;
  top: calc(var(--spacing-workspace-header) + env(safe-area-inset-top));
  height: calc(var(--app-viewport-height) - var(--spacing-workspace-header) - env(safe-area-inset-top));
  overflow-y: auto;
  padding: 24px 12px 16px;
  background: var(--color-paper-deep);
  border-right: 1px solid var(--color-line);
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.workspace-sidebar-controls { display: flex; justify-content: flex-end; }
.workspace-sidebar-toggle {
  display: inline-flex;
  min-height: 44px;
  min-width: 44px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: var(--radius-sm);
  color: var(--color-ink-soft);
  cursor: pointer;
}
.workspace-sidebar-toggle:hover { color: var(--color-accent); background: var(--color-accent-tint); }
.workspace-sidebar-toggle-label { font-size: 13px; font-weight: 500; }
.workspace-grid[data-sidebar="expanded"] .workspace-sidebar-toggle { width: 100%; justify-content: flex-start; padding: 8px 12px; }
.workspace-nav-link { display: flex; align-items: center; gap: 12px; min-height: 44px; padding: 10px 12px; border-radius: var(--radius-sm); color: var(--color-ink-soft); font-size: 14px; text-decoration: none; }
.workspace-nav-link:hover { background: var(--color-paper-card); color: var(--color-ink); }
.workspace-nav-link.is-active { background: var(--color-accent-tint); color: var(--color-accent-deep); font-weight: 600; }
.workspace-nav-label { min-width: 0; }
.workspace-nav-shortcut { margin-left: auto; font: 10px var(--font-mono); color: var(--color-ink-faint); }
.workspace-nav-section { margin: 0 12px 8px; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--color-ink-faint); }
.workspace-sidebar-resources { border-top: 1px solid var(--color-line); padding-top: 16px; }
.workspace-sidebar-footer { margin-top: auto; padding-top: 16px; }
.workspace-rewrite { display: flex; align-items: center; gap: 12px; min-height: 44px; width: 100%; padding: 12px; border: 1px solid var(--color-line); border-radius: var(--radius-sm); background: var(--color-paper-raised); color: var(--color-ink); text-align: left; font-size: 13px; cursor: pointer; }
.workspace-rewrite:hover { color: var(--color-accent); border-color: var(--color-accent); }

.workspace-grid[data-sidebar="collapsed"] .workspace-sidebar { padding: 16px 8px; }
.workspace-grid[data-sidebar="collapsed"] .workspace-sidebar-controls { justify-content: center; }
.workspace-grid[data-sidebar="collapsed"] .workspace-sidebar-toggle-label,
.workspace-grid[data-sidebar="collapsed"] .workspace-sidebar .workspace-nav-label,
.workspace-grid[data-sidebar="collapsed"] .workspace-nav-shortcut,
.workspace-grid[data-sidebar="collapsed"] .workspace-nav-section { display: none; }
.workspace-grid[data-sidebar="collapsed"] .workspace-nav-link,
.workspace-grid[data-sidebar="collapsed"] .workspace-rewrite { justify-content: center; padding: 12px 8px; }

.workspace-column, .workspace-main { min-width: 0; width: 100%; }
.workspace-main > * { min-width: 0; width: 100%; }
.workspace-main > div:first-child { padding-top: 28px; }
.workspace-column:has(.workspace-full-height) {
  height: calc(var(--app-viewport-height) - var(--spacing-workspace-header) - env(safe-area-inset-top));
  display: flex;
  flex-direction: column;
}
.workspace-main:has(.workspace-full-height) { min-height: 0; flex: 1; display: flex; flex-direction: column; }
.workspace-main > .workspace-full-height { padding-top: 0; }
.workspace-main textarea { field-sizing: content; min-height: 88px; max-height: calc(45dvh / var(--app-zoom, 1)); }
.workspace-guidance { padding: 12px 24px; border-bottom: 1px solid var(--color-line); background: var(--color-paper-card); flex-shrink: 0; }
.workspace-guidance-row { display: flex; gap: 16px; align-items: center; justify-content: space-between; min-width: 0; }
.workspace-guidance-title { min-width: 0; flex: 1; display: flex; align-items: center; gap: 12px; }
.workspace-guidance-title a { min-width: 0; font-size: 14px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.workspace-guidance-actions { display: flex; gap: 4px; align-items: center; flex-shrink: 0; }
.workspace-guidance-actions button, .workspace-guidance-actions a { min-width: 36px; min-height: 36px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 6px; border-radius: var(--radius-sm); color: var(--color-ink-soft); cursor: pointer; }
.workspace-guidance-actions button:hover, .workspace-guidance-actions a:hover { color: var(--color-accent); background: var(--color-accent-tint); }
.workspace-guidance-actions button:disabled { opacity: .5; cursor: wait; }
.workspace-guidance-count { font: 11px var(--font-mono); color: var(--color-ink-faint); }

@media (max-width: 767.98px) {
