/** Titre par défaut : <title> du HTML, sinon basename sans extension. */
function deriveTitle(html: string, real: string): string {
  const m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  const title = m ? m[1].replace(/\s+/g, ' ').trim() : '';
  if (title) return title;
  return path.basename(real).replace(/\.[^.]+$/, '') || 'Sans titre';
}

