content.content:
  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(timer);
  }, [toast]);

  const visible = useMemo(() => {
    const needle = query.trim().toLowerCase();

    return items
      .filter((item) => !project || item.projectSlug === project)
      .filter((item) => !kind || item.kind === kind)
      .filter((item) => !priority || (item.priority ?? 'normal') === priority)
      .filter((item) => runtime === 'all' || (item.origin?.runtime ?? 'unknown') === runtime)
      .filter((item) => {
        if (!needle) return true;
        return [
          item.itemTitle,
          item.prompt,
          item.context,
          item.conversationTitle,
          item.projectName,
        ]
          .filter(Boolean)
          .some((value) => value!.toLowerCase().includes(needle));
      })
      .sort((a, b) => {
        if (sort === 'urgency') {
          return (
            PRIORITY_RANK[b.priority ?? 'normal'] - PRIORITY_RANK[a.priority ?? 'normal'] ||
            timestamp(b.conversationUpdatedAt) - timestamp(a.conversationUpdatedAt)
          );
        }
        if (sort === 'recent') {
          return timestamp(b.conversationUpdatedAt) - timestamp(a.conversationUpdatedAt);
        }
        return (
          a.projectName.localeCompare(b.projectName, 'fr') ||
          // D5 (chantier provenance-session, lot 8) : une session inactive
          // depuis plus de 30 min remonte en tête de SON groupe projet.
          Number(Boolean(b.sessionIdleSince)) - Number(Boolean(a.sessionIdleSince)) ||
          PRIORITY_RANK[b.priority ?? 'normal'] - PRIORITY_RANK[a.priority ?? 'normal']
        );
      });
  }, [items, kind, priority, project, query, runtime, sort]);

  const urgentCount = items.filter((item) => item.priority === 'urgent').length;

  return (
    <div className="mx-auto w-full min-w-0 max-w-6xl px-4 py-6 sm:px-8 sm:py-8">
      <header className="mb-4 flex flex-wrap items-end justify-between gap-2">
        <div>
          <h1 className="mt-1.5 font-display text-4xl leading-none text-ink sm:text-[2.75rem]">
            {t('nav.inbox')}
          </h1>
          <p className="mt-2 max-w-2xl text-sm leading-relaxed text-ink-soft">
            {t('ux.inboxDescription', 'Ce qui attend ta réponse.')}
          </p>
        </div>
      </header>

      <nav className="inbox-summary" aria-label={t('ux.inboxSummary', 'Choisir les demandes à traiter')}>
        <button className="glass-control" type="button" aria-pressed={lane === 'responses' && priority !== 'urgent'} onClick={() => setView({ lane: 'responses', priority: '', project: '', kind: '', runtime: 'all', q: '' })}>
          <strong>{state === 'ready' ? items.length : '—'}</strong>{t('ux.inboxAwaiting', 'À répondre')}
        </button>
        <button className="glass-control" type="button" aria-pressed={lane === 'responses' && priority === 'urgent'} onClick={() => setView({ lane: 'responses', priority: 'urgent', project: '', kind: '', runtime: 'all', q: '', sort: 'urgency' })}>
          <strong>{state === 'ready' ? urgentCount : '—'}</strong>{t('ux.inboxUrgencies', 'Urgences')}
        </button>
        <button className="glass-control" type="button" aria-pressed={lane === 'reviews'} onClick={() => setView({ lane: 'reviews' })}>
          <strong>{reviewError ? '—' : reviewThreads?.length ?? '—'}</strong>{t('ux.inboxReviews', 'Revues ouvertes')}
        </button>
      </nav>

      <section className="mb-4" hidden={lane !== 'responses'}>
        <CollectionControls
          searchSlot={
            <Input
              id="inbox-search"
              type="search"
              aria-label={t('common.searchButton', 'Recherche')}
              className="min-w-0"
              value={query}
              onChange={(event) => setView({ q: event.target.value })}
              placeholder={t('inboxPage.searchPlaceholder', 'Texte, contexte...')}
            />
          }
          activeCount={
            Number(Boolean(project)) + Number(Boolean(kind)) + Number(Boolean(priority)) + Number(runtime !== 'all')
          }
          resultCount={visible.length}
          summary={[
            projects.find((item) => item.slug === project)?.name || project,
            ITEM_TYPES.find(([value]) => value === kind)?.[1],
            PRIORITIES.find((item) => item.value === priority)?.label,
            runtime !== 'all' ? t(AGENT_RUNTIME_META[runtime as AgentRuntime].i18nKey) : '',
            sort !== 'urgency'
              ? t(sort === 'project' ? 'inboxPage.sortProject' : 'inboxPage.sortRecent')
              : '',
          ]
            .filter(Boolean)
            .join(' · ')}
          filters={
            <div className="space-y-3">
              <div className="grid min-w-0 gap-3 sm:grid-cols-2 lg:grid-cols-4">
                <Dropdown
                  label={t('common.project')}
                  value={project}
                  onChange={(v) => setView({ project: v })}
                  options={[
                    { value: '', label: t('ux.allProjects') },
                    ...projects.map((item) => ({ value: item.slug, label: item.name })),
                  ]}
                />
                <Dropdown
                  label={t('inboxPage.type', 'Type')}
                  value={kind}
                  onChange={(v) => setView({ kind: v })}
                  options={[
                    { value: '', label: t('inboxPage.filterAll', 'Tous') },
                    ...ITEM_TYPES.map(([value, label]) => ({ value, label })),
                  ]}
                />
                <Dropdown
                  label={t('inboxPage.priority', 'Priorité')}
                  value={priority}
                  onChange={(v) => setView({ priority: v })}
                  options={[
                    { value: '', label: t('inboxPage.filterAllFem', 'Toutes') },
                    ...PRIORITIES.map((item) => ({ value: item.value, label: item.label })),
                  ]}
                />
                <RuntimeFilter value={runtime} onChange={(v) => setView({ runtime: v })} />
              </div>
              <button
                type="button"
                onClick={() => setView({ project: '', kind: '', priority: '', runtime: 'all', q: '', sort: 'urgency' })}
                data-density="compact"
                className="glass-control self-start rounded-lg px-3 text-sm text-ink-soft hover:bg-paper-deep hover:text-ink"
              >
                {t('common.reset', 'Réinitialiser')}
              </button>
            </div>
          }
          display={
            <Dropdown
              label={t('inboxPage.sort', 'Tri')}
              value={sort}
              onChange={(v) => setView({ sort: v as SortMode })}
              options={[
                { value: 'project', label: t('inboxPage.sortProject', 'Par projet') },
                { value: 'urgency', label: t('inboxPage.sortUrgency', 'Par urgence') },
                { value: 'recent', label: t('inboxPage.sortRecent', 'Plus récents') },
              ]}
            />
          }
        />
      </section>

      {lane === 'responses' && state === 'error' && (
        <div className="mb-6 rounded-lg border border-accent/30 bg-accent/5 px-4 py-3 text-sm text-accent-deep">
          {error}
        </div>
      )}

      <section hidden={lane !== 'responses'} aria-label={t('ux.inboxAwaiting', 'À répondre')}>
        {state === 'loading' ? (
          <div className="h-72 animate-pulse rounded-lg border border-line bg-paper-card/70" aria-busy />
        ) : state === 'ready' || items.length > 0 ? (
          <InboxList
            items={visible}
            groupByProject={sort === 'project'}
            onItemResolved={handleItemResolved}
            filtered={Boolean(project || kind || priority || query || runtime !== 'all')}
            onReset={() => setView({ project: '', kind: '', priority: '', runtime: 'all', q: '', sort: 'urgency' })}
          />
        ) : null}
      </section>
      <section hidden={lane !== 'reviews'} aria-label={t('ux.inboxReviews', 'Revues ouvertes')}>
        <HtmlReviewInboxSection threads={reviewThreads} error={reviewError} onRetry={() => void fetchReviews()} />
      </section>

      {toast && (
        <div
          role="status"
          className="rise fixed bottom-20 left-1/2 z-50 -translate-x-1/2 rounded-full bg-ink px-5 py-2.5 text-sm font-medium text-ink-inverse shadow-lift"
        >
          {toast}
        </div>
      )}
    </div>
  );
}

function timestamp(value: string | undefined) {
  if (!value) return 0;
  const time = Date.parse(value);
  return Number.isNaN(time) ? 0 : time;
}
