import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import os from 'node:os';
import path from 'node:path';
import { mkdtemp, mkdir, writeFile, readFile, rm, realpath } from 'node:fs/promises';

let root = '';
let registry!: typeof import('./registry');
let store!: typeof import('./store');

const ISO = '2026-01-01T00:00:00.000Z';

beforeAll(async () => {
  root = await realpath(await mkdtemp(path.join(os.tmpdir(), 'wsreg-')));
  await mkdir(path.join(root, 'data', 'html-review'), { recursive: true });
  process.env.WORKSTATION_ROOT = root;
  process.env.HTML_REVIEW_ROOTS = root;
  registry = await import('./registry');
  store = await import('./store');
});

afterAll(async () => {
  if (root) await rm(root, { recursive: true, force: true });
});

async function fixture(name: string, title: string, body: string): Promise<string> {
  const p = path.join(root, name);
  await writeFile(p, `<html><head><title>${title}</title></head><body><p>${body}</p></body></html>`);
  return p;
}

describe('registry', () => {
  test('addDoc dérive le titre du <title> et est idempotent', async () => {
    const p = await fixture('plan.html', 'Plan produit', 'contenu');
    const a = await registry.addDoc(p);
    expect(a.title).toBe('Plan produit');
    expect(a.path).toBe(p);
    const b = await registry.addDoc(p);
    expect(b.docId).toBe(a.docId);
    expect(b.addedAt).toBe(a.addedAt); // addedAt préservé
    const raw = await registry.listRaw();
    expect(raw.filter((d) => d.docId === a.docId).length).toBe(1); // pas de doublon
  });

