export async function addDoc(inputPath: string, origin?: AgentOrigin): Promise<ReviewDoc> {
  const real = await resolveSafeHtmlPath(inputPath);
  const docId = docIdForPath(real);
  const html = await readFile(real, 'utf8');
  const title = deriveTitle(html, real);
  const persistentStateId = extractPersistentStateId(html);

  return serialize(async () => {
    const reg = await readRegistryForWrite();
    const existing = reg.docs.find((d) => d.docId === docId);
    if (persistentStateId) {
      const binding = reg.docs.find(
        (doc) => doc.persistentStateId === persistentStateId && doc.docId !== docId,
      );
      if (binding) {
        if (await existingFile(binding.path)) {
          throw new Error(`l'identifiant persistant ${persistentStateId} est déjà lié à un autre document`);
        }
        reg.docs = reg.docs.filter((doc) => doc.docId !== binding.docId);
      }
    }
    // Repart de l'entrée EXISTANTE (spread en premier) et ne réinitialise
    // explicitement que ce qui doit l'être. Avant ce correctif, l'entrée était
    // reconstruite de zéro (seul `assets` était préservé à la main) : tout
    // futur champ optionnel aurait été effacé silencieusement à chaque
    // ré-ingestion htmlshare automatique (~5 min). Ce pattern ferme la fenêtre
    // pour TOUT champ futur, pas seulement `audioLanguage`.
    const entry: ReviewDoc = {
      ...existing,
      docId,
      path: real,
      title,
      addedAt: existing?.addedAt ?? new Date().toISOString(),
      // Défaut calculé une seule fois, à la première inscription ; préservé
      // (jamais recalculé) si déjà présent — sinon une bascule manuelle via
      // PUT /:docId/audio-language serait effacée à la ré-ingestion suivante.
      audioLanguage: existing?.audioLanguage ?? deduceAudioLanguage(html, docId),
      persistentStateId,
      origin: existing ? mergeOrigin(existing.origin, origin) : origin,
    };
    reg.docs = [...reg.docs.filter((d) => d.docId !== docId), entry];
    await writeRegistry(reg);
    return entry;
  });
}

