const NAMED_ENTITIES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
};

/**
 * Décode les entités d'un texte brut extrait du HTML (`<title>` est du texte
 * échappé : « Profils &amp; personas » doit s'afficher « Profils & personas »).
 * Une seule passe : `&amp;lt;` donne `&lt;`, jamais `<`. Une entité inconnue
 * reste telle quelle. Le résultat est du TEXTE, rendu échappé par React.
 */
export function decodeHtmlEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, body: string) => {
    if (body[0] === '#') {
      const code = body[1] === 'x' || body[1] === 'X' ? parseInt(body.slice(2), 16) : parseInt(body.slice(1), 10);
      return Number.isInteger(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : match;
    }
    return NAMED_ENTITIES[body.toLowerCase()] ?? match;
  });
}

