async function readRegistry(): Promise<ReviewRegistry> {
  const raw = await readRawRegistryFile();
  if (raw == null || raw.trim() === '') return { docs: [] };
  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch (err) {
    console.warn(
      '[html-review/registry] registry.json illisible (JSON invalide) — lecture tolérante, {docs: []} renvoyé :',
      err,
    );
    return { docs: [] };
  }
  const parsed = ReviewRegistrySchema.safeParse(json);
  if (!parsed.success) {
    console.warn(
      '[html-review/registry] registry.json invalide (échec de validation zod) — lecture tolérante, {docs: []} renvoyé :',
      parsed.error.message,
    );
    return { docs: [] };
  }
  // Titres inscrits avant le décodage des entités (« &amp; » affiché brut) :
  // corrigés à la lecture ; la prochaine ré-ingestion les réécrit décodés.
  return { ...parsed.data, docs: parsed.data.docs.map((doc) => ({ ...doc, title: decodeHtmlEntities(doc.title) })) };
}

/**
 * Lecture STRICTE, utilisée juste avant toute écriture (`addDoc`/`setAssets`/
 * `removeDoc`/`setAudioLanguage`). `readRegistry()` ci-dessus est tolérant pour
 * ne pas casser les listages, mais un WRITE qui repart d'un `{docs: []}` obtenu
 * par échec de parse/validation écraserait silencieusement TOUTES les entrées
 * existantes au prochain `writeRegistry`. Ici, un fichier vraiment absent ou
 * vide (zéro octet) reste un premier enregistrement légitime — mais un fichier
 * NON-vide sur disque qui échoue à parser/valider fait échouer l'écriture
 * explicitement plutôt que de l'écraser.
 */
async function readRegistryForWrite(): Promise<ReviewRegistry> {
  const raw = await readRawRegistryFile();
  if (raw == null || raw.trim() === '') return { docs: [] };
  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch (err) {
    console.warn(
      '[html-review/registry] registry.json illisible (JSON invalide) au moment d’écrire — écriture refusée :',
      err,
    );
    throw new Error(
      'registry.json est corrompu (JSON invalide) : écriture refusée pour éviter un écrasement silencieux. Réparez ou restaurez data/html-review/registry.json avant de réessayer.',
    );
  }
  const parsed = ReviewRegistrySchema.safeParse(json);
  if (!parsed.success) {
    console.warn(
      '[html-review/registry] registry.json invalide (échec de validation zod) au moment d’écrire — écriture refusée :',
      parsed.error.message,
    );
    throw new Error(
      'registry.json est corrompu (échec de validation) : écriture refusée pour éviter un écrasement silencieux. Réparez ou restaurez data/html-review/registry.json avant de réessayer.',
    );
  }
  return parsed.data;
}

async function writeRegistry(reg: ReviewRegistry): Promise<void> {
  await atomicWrite(registryPath(), JSON.stringify(reg, null, 2));
}

