function out(s: string): void {
  process.stdout.write(s.endsWith('\n') ? s : s + '\n');
}

/** Titre : <title>, sinon premier <h1> (tags internes retirés), sinon le
 *  `fallback` fourni par l'appelant. Regex simple — pas de parseur HTML,
 *  suffisant pour les documents template-authored de ce système. */
